mapper.select:
SELECT
    T1.USERID AS userId,
    T1.USERNAME AS username,
    T2.MARKET AS market
FROM HDOC_USER_INFOR T1
INNER JOIN HDOC_MARKET_AUTH T2 
ON T1.USERID = T2.USERID


        AND T1.USERID = #{userId}


        AND T1.USERNAME = #{username}


        AND T2.MARKET = #{market}


        AND T2.TYPE = #{type}


ORDER BY T1.USERID, T2.MARKET
